/* WorkticAI V27.15 — Partner Business Backoffice */
(() => {
  const $ = s => document.querySelector(s);
  const $$ = s => Array.from(document.querySelectorAll(s));
  const E = v => typeof esc === 'function' ? esc(v ?? '') : String(v ?? '').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const M = v => `${Number(v||0).toLocaleString('es-CO',{minimumFractionDigits:2,maximumFractionDigits:2})} USD`;
  const D = v => { if(!v) return '—'; try{return new Date(v).toLocaleDateString('es-CO')}catch{return v} };
  const DT = v => { if(!v) return '—'; try{return new Date(v).toLocaleString('es-CO')}catch{return v} };
  const notify = m => typeof toast === 'function' ? toast(m) : console.log(m);
  const request = (url,opt) => api(url,opt);
  const labelStatus = s => ({pending:'Pendiente',available:'Disponible',paid:'Pagada',reversed:'Reversada',requested:'Solicitado',approved:'Aprobado',processing:'Procesando',rejected:'Rechazado',cancelled:'Cancelado',needs_review:'Requiere revisión',active:'Activo',won:'Ganado',open:'Abierta',pending_review:'Por revisar',paused:'Pausada',closed:'Cerrada',applied:'Aplicado',accepted:'Aceptado',withdrawn:'Retirado',reported:'Reportada',business_confirmed:'Confirmada por empresa',business_rejected:'Rechazada por empresa',certified:'Certificado',passed:'Aprobado',failed:'No aprobado',revoked:'Revocado',in_training:'En formación',exam_pending:'Examen pendiente',not_certified:'Sin certificar'})[s]||s||'—';
  const badgeClass = s => ['available','paid','approved','accepted','active','won','open','certified','passed','business_confirmed'].includes(s)?'good':['rejected','reversed','revoked','chargeback','refunded','business_rejected'].includes(s)?'bad':['pending','pending_review','requested','processing','needs_review','exam_pending','in_training','reported'].includes(s)?'warn':'';
  const commissionLabel = t => ({direct:'Venta directa',renewal:'Renovación',adoption:'Adopción',network:'Comunidad',mentorship:'Mentoría',cosell_referrer:'Co-Sell · Referidor',cosell_closer:'Co-Sell · Closer',human_sales:'Human Sales',payout_debit:'Payout',refund_reversal:'Reverso · Reembolso',chargeback_reversal:'Reverso · Chargeback',human_sales_reversal:'Reverso · Human Sales'})[t]||t;
  const state = {overview:null,ranks:[],me:null,view:'home',networkMode:'tree',lastAutopilot:null};

  const navItems = [
    ['home','⌂','Inicio'],['network','◎','Mi Red'],['clients','◫','Mis Clientes'],['commissions','$','Comisiones'],['momentum','↗','Momentum'],['cosell','⇄','Co-Sell'],['activate','✓','Activate Certified'],['marketplace','▦','Oportunidades'],['payouts','↙','Payouts'],['autopilot','✦','Partner Autopilot'],['settings','⚙','Configuración']
  ];

  function topbar(title, desc, actions=''){
    return `<div class="pc15-topbar"><div><h2>${E(title)}</h2><p>${E(desc)}</p></div><div class="pc15-top-actions">${actions}</div></div>`;
  }
  function empty(title, desc=''){return `<div class="pc15-empty"><b>${E(title)}</b><span>${E(desc)}</span></div>`}
  function statusBadge(s){return `<span class="pc15-badge ${badgeClass(s)}">${E(labelStatus(s))}</span>`}
  function setBusy(el,text='Procesando…'){ if(el){el.disabled=true;el.dataset.oldText=el.textContent;el.textContent=text;} }
  function unBusy(el){ if(el){el.disabled=false;if(el.dataset.oldText)el.textContent=el.dataset.oldText;} }

  async function loadBase(){
    const [ov, ranks, me] = await Promise.all([request('/api/partners/overview'),request('/api/partners/ranks'),request('/api/auth/me').catch(()=>null)]);
    state.overview=ov; state.ranks=ranks||[]; state.me=me;
    return ov;
  }

  function activationScreen(d){
    const can = !!d.can_activate;
    return `<div class="pc15-activate-screen"><span class="pc15-eyebrow">WORKTIC PARTNERS</span><h2>${can?'Activa tu Partner Business Backoffice':'Partner Center requiere una licencia de pago'}</h2><p>${can?'Tendrás un backoffice independiente dentro de WorkticAI para gestionar red, clientes, comisiones, Co-Sell, Activate Certified, Human Sales, payouts y Autopilot. El CRM permanece separado y conectado.':'Tu cuenta puede seguir usando WorkticAI según su plan, pero para acceder al programa de Partners necesitas una licencia Personal, Negocio o Empresa vigente.'}</p>${can?'<button class="pc15-btn" id="pc15Activate">Activar Partner Center</button>':'<button class="pc15-btn" id="pc15GoBilling">Ver planes WorkticAI</button>'}</div>`;
  }

  function shell(){
    const o=state.overview||{}, p=o.profile||{};
    return `<div class="pc15-shell" id="pc15Shell"><div class="pc15-partner-backdrop" id="pc15PartnerBackdrop"></div><aside class="pc15-rail"><button type="button" class="pc15-rail-close" id="pc15RailClose" aria-label="Cerrar menú Partner">✕</button><div class="pc15-brand"><div><small>WORKTIC PARTNERS</small><b>Partner Center</b><span>Tu backoffice comercial independiente</span></div><span class="pc15-rank-pill">${E(p.rank_name||p.rank_code||'Spark')}</span></div><nav class="pc15-nav">${navItems.map(([id,ico,name])=>`<button type="button" data-p15-view="${id}" class="${id===state.view?'active':''}"><span class="ico">${ico}</span>${E(name)}</button>`).join('')}</nav><div class="pc15-rail-foot"><b>${E(p.partner_code||'Partner')}</b><br>CRM, Billing, Academy y Analytics conectados sin duplicar tu operación.</div></aside><div class="pc15-work"><div class="pc15-workspace-tools"><button type="button" class="pc15-workspace-tool pc15-partner-menu-trigger" id="pc15PartnerMenuBtn"><span>☰</span><b>Menú Partner</b></button><div class="pc15-workspace-toolset"><button type="button" class="pc15-workspace-tool" id="pc15ToggleCRM"><span>◫</span><b>Expandir CRM</b></button><button type="button" class="pc15-workspace-tool" id="pc15FocusMode"><span>◉</span><b>Modo enfoque Partner</b></button><button type="button" class="pc15-workspace-tool" id="pc15Fullscreen"><span>⛶</span><b>Pantalla completa</b></button><button type="button" class="pc15-workspace-tool pc15-workspace-back" id="pc15BackCRM"><span>←</span><b>Volver al CRM</b></button></div></div><div id="pc15Content"><div class="pc15-loading">Cargando Partner Center…</div></div></div></div>`;
  }

  function isPartnerWorkspace(){ return document.body.classList.contains('partner-workspace'); }
  function setPartnerWorkspace(active){
    document.body.classList.toggle('partner-workspace',!!active);
    if(!active){
      document.body.classList.remove('partner-crm-expanded','partner-focus');
      document.documentElement.classList.remove('pc15-partner-menu-lock');
      $('#pc15Shell')?.classList.remove('partner-menu-open');
    }
  }
  function syncWorkspaceButtons(){
    const expanded=document.body.classList.contains('partner-crm-expanded');
    const focus=document.body.classList.contains('partner-focus');
    const crm=$('#pc15ToggleCRM b'); if(crm) crm.textContent=expanded?'Colapsar CRM':'Expandir CRM';
    const fm=$('#pc15FocusMode b'); if(fm) fm.textContent=focus?'Salir de enfoque':'Modo enfoque Partner';
    const fs=$('#pc15Fullscreen b'); if(fs) fs.textContent=document.fullscreenElement?'Salir pantalla completa':'Pantalla completa';
  }
  function closePartnerDrawer(){
    $('#pc15Shell')?.classList.remove('partner-menu-open');
    document.documentElement.classList.remove('pc15-partner-menu-lock');
  }
  function bindWorkspaceControls(){
    setPartnerWorkspace(true);
    const crm=$('#pc15ToggleCRM');
    if(crm) crm.onclick=()=>{
      document.body.classList.remove('partner-focus');
      document.body.classList.toggle('partner-crm-expanded');
      syncWorkspaceButtons();
    };
    const focus=$('#pc15FocusMode');
    if(focus) focus.onclick=()=>{
      document.body.classList.remove('partner-crm-expanded');
      document.body.classList.toggle('partner-focus');
      syncWorkspaceButtons();
    };
    const fs=$('#pc15Fullscreen');
    if(fs) fs.onclick=async()=>{
      try{
        if(document.fullscreenElement) await document.exitFullscreen();
        else await document.documentElement.requestFullscreen();
      }catch(e){ notify('El navegador no permitió pantalla completa.'); }
      syncWorkspaceButtons();
    };
    const back=$('#pc15BackCRM'); if(back) back.onclick=()=>switchMainView('dashboard');
    const menu=$('#pc15PartnerMenuBtn'); if(menu) menu.onclick=()=>{$('#pc15Shell')?.classList.add('partner-menu-open');document.documentElement.classList.add('pc15-partner-menu-lock')};
    const close=$('#pc15RailClose'); if(close) close.onclick=closePartnerDrawer;
    const backdrop=$('#pc15PartnerBackdrop'); if(backdrop) backdrop.onclick=closePartnerDrawer;
    syncWorkspaceButtons();
  }

  function bindNav(){
    $$('[data-p15-view]').forEach(b=>b.onclick=()=>{openView(b.dataset.p15View);closePartnerDrawer()});
  }

  async function openView(view){
    state.view=view;
    $$('[data-p15-view]').forEach(b=>b.classList.toggle('active',b.dataset.p15View===view));
    const c=$('#pc15Content'); if(!c)return; c.innerHTML='<div class="pc15-loading">Cargando…</div>';
    try{
      if(view==='home') return renderHome(c);
      if(view==='network') return renderNetwork(c);
      if(view==='clients') return renderClients(c);
      if(view==='commissions') return renderCommissions(c);
      if(view==='momentum') return renderMomentum(c);
      if(view==='cosell') return renderCosell(c);
      if(view==='activate') return renderActivate(c);
      if(view==='marketplace') return renderMarketplace(c);
      if(view==='payouts') return renderPayouts(c);
      if(view==='autopilot') return renderAutopilot(c);
      if(view==='settings') return renderSettings(c);
    }catch(e){ c.innerHTML=topbar('Partner Center','')+empty('No fue posible cargar esta sección',e.message||'Intenta de nuevo.'); }
  }

  function renderHome(c){
    const o=state.overview||{},p=o.profile||{},s=o.stats||{},b=o.balances||{},r=o.rank||{},cert=o.certification||{};
    const licenseWarning = o.eligible===false ? `<div class="pc15-license-warning"><b>Tu licencia de pago no está vigente.</b>Conservamos historial y atribuciones, pero nuevas comisiones y acciones Partner quedan bloqueadas hasta renovar.</div>`:'';
    c.innerHTML=`${topbar('Inicio','Resumen de tu negocio Partner.',`<button class="pc15-btn secondary" id="pc15Refresh">Actualizar</button><button class="pc15-btn" id="pc15Public">Ver programa</button>`)}${licenseWarning}<div class="pc15-dashboard-hero"><section class="pc15-hero-main"><span class="pc15-eyebrow">USA · COMPARTE · ACTIVA · CRECE</span><h3>Un negocio Partner conectado a todo WorkticAI.</h3><p>Tu CRM gestiona prospectos y oportunidades. Partner Center se ocupa de atribución, red, Momentum, comisiones, Co-Sell, especialistas, oportunidades Human Sales y pagos.</p><div class="pc15-top-actions" style="margin-top:15px"><button class="pc15-btn" data-p15-go="autopilot">Crear plan con Autopilot</button><button class="pc15-btn secondary" data-p15-go="network">Ver mi red</button></div></section><aside class="pc15-id-card"><div class="pc15-id-row"><div><small>Código Partner</small><b class="pc15-code">${E(p.partner_code||'—')}</b></div><span class="pc15-rank-pill">${E(p.rank_name||p.rank_code||'Spark')}</span></div><div class="pc15-id-row"><div><small>Comisión directa actual</small><b>${Number(r.direct_percent||0)}%</b></div><div style="text-align:right"><small>Activate</small>${statusBadge(cert.status||p.activate_status)}</div></div><div><small style="color:#877c8d;font-size:10px">Enlace inteligente</small><div class="pc15-ref"><input id="pc15Referral" readonly value="${E(o.referral_url||'')}"><button class="pc15-btn secondary" id="pc15Copy">Copiar</button></div></div></aside></div><div class="pc15-grid pc15-kpis"><div class="pc15-kpi"><small>Clics</small><b>${s.clicks||0}</b><em>Enlace Partner</em></div><div class="pc15-kpi"><small>Registros</small><b>${s.signups||0}</b><em>Atribuidos</em></div><div class="pc15-kpi"><small>Clientes</small><b>${s.direct_active||0}</b><em>Activos directos</em></div><div class="pc15-kpi"><small>Adopción</small><b>${s.adopted_active||0}</b><em>Clientes validados</em></div><div class="pc15-kpi"><small>Red N2 + N3</small><b>${Number(s.level2_partners||0)+Number(s.level3_partners||0)}</b><em>${s.level2_partners||0} N2 · ${s.level3_partners||0} N3</em></div><div class="pc15-kpi"><small>Oportunidades</small><b>${s.marketplace_open||0}</b><em>Human Sales abiertas</em></div></div><div class="pc15-grid pc15-balances"><div class="pc15-card pc15-balance available"><small>Disponible</small><b>${M(b.available)}</b></div><div class="pc15-card pc15-balance pending"><small>Pendiente / programado</small><b>${M(b.pending)}</b></div><div class="pc15-card pc15-balance"><small>Reservado en payouts</small><b>${M(b.reserved)}</b></div><div class="pc15-card pc15-balance"><small>Pagado histórico</small><b>${M(b.paid)}</b></div></div><div class="pc15-grid pc15-paths"><article class="pc15-card pc15-path"><span class="num">01</span><h4>Share · Recomienda</h4><p>Comparte tu enlace y recibe atribución automática cuando el prospecto se registra.</p><span class="state">Activo</span></article><article class="pc15-card pc15-path"><span class="num">02</span><h4>Sell · Construye cartera</h4><p>Trabaja tus prospectos desde CRM, Copilot, demos y seguimiento.</p><span class="state">CRM conectado</span></article><article class="pc15-card pc15-path"><span class="num">03</span><h4>Activate Certified</h4><p>Certifícate para implementaciones y Human Sales con empresas.</p><span class="state">${E(labelStatus(cert.status||p.activate_status))}</span></article><article class="pc15-card pc15-path"><span class="num">04</span><h4>Lead · Comunidad</h4><p>Desarrolla Partners y desbloquea N2, N3 y mentoría por desempeño.</p><span class="state">${E(p.rank_name||p.rank_code||'Spark')}</span></article></div>`;
    $('#pc15Refresh')?.addEventListener('click',()=>loadPartnersV2715(true));
    $('#pc15Public')?.addEventListener('click',()=>window.open('/partners.html','_blank'));
    $('#pc15Copy')?.addEventListener('click',async()=>{const v=$('#pc15Referral')?.value||'';try{await navigator.clipboard.writeText(v);notify('Enlace Partner copiado')}catch{}});
    $$('[data-p15-go]').forEach(b=>b.onclick=()=>openView(b.dataset.p15Go));
  }

  async function renderNetwork(c){
    const d=await request('/api/partners/network/tree'), nodes=d.nodes||[], counts=d.counts||{};
    c.innerHTML=`${topbar('Mi Red','Visualiza hasta tres niveles de comunidad y sus métricas.',`<button class="pc15-btn secondary" id="pc15NetworkMode">${state.networkMode==='tree'?'Ver lista':'Ver árbol'}</button>`)}<div class="pc15-grid pc15-kpis"><div class="pc15-kpi"><small>Directos</small><b>${counts.direct||0}</b></div><div class="pc15-kpi"><small>Nivel 2</small><b>${counts.level2||0}</b></div><div class="pc15-kpi"><small>Nivel 3</small><b>${counts.level3||0}</b></div><div class="pc15-kpi"><small>Total red</small><b>${counts.total||0}</b></div></div><div id="pc15NetworkBody"></div>`;
    const draw=()=>{const body=$('#pc15NetworkBody');if(!body)return;if(state.networkMode==='list'){body.innerHTML=nodes.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Nivel</th><th>Partner</th><th>Código</th><th>Rango</th><th>Clientes</th><th>Adopción</th><th>Activate</th><th>Estado</th></tr></thead><tbody>${nodes.map(n=>`<tr><td>N${n.level}</td><td><b>${E(n.name)}</b><small>${E(n.email)}</small></td><td>${E(n.partner_code)}</td><td>${E(n.rank_code)}</td><td>${n.direct_active||0}</td><td>${n.adopted_active||0}</td><td>${statusBadge(n.activate_status)}</td><td>${statusBadge(n.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('Tu red aún no tiene Partners','Cuando clientes atribuidos activen Partner Center aparecerán aquí.');return;}const levels=[1,2,3];body.innerHTML=`<div class="pc15-tree"><div class="pc15-tree-level"><div class="pc15-tree-node root"><b>Tú · ${E(state.overview?.profile?.partner_code||'Partner')}</b><small>${E(state.overview?.profile?.rank_name||state.overview?.profile?.rank_code||'Spark')}</small></div></div>${levels.map(l=>{const xs=nodes.filter(n=>n.level===l);return xs.length?`<div class="pc15-tree-level">${xs.map(n=>`<div class="pc15-tree-node"><b>${E(n.name)}</b><small>${E(n.partner_code)} · N${l}</small><span class="pc15-badge ${n.status==='active'?'good':''}">${E(n.rank_code)}</span></div>`).join('')}</div>`:''}).join('')}</div>`};draw();$('#pc15NetworkMode').onclick=()=>{state.networkMode=state.networkMode==='tree'?'list':'tree';$('#pc15NetworkMode').textContent=state.networkMode==='tree'?'Ver lista':'Ver árbol';draw()};
  }

  async function renderClients(c){
    const xs=await request('/api/partners/customers');
    c.innerHTML=`${topbar('Mis Clientes','Clientes atribuidos por tu actividad Partner. Para gestión comercial abre el CRM.',`<button class="pc15-btn" id="pc15CRM">Abrir CRM</button>`)}${xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Cliente</th><th>Plan</th><th>Impact Score</th><th>Adopción</th><th>Vencimiento</th><th>Atribuido</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.name)}</b><small>${E(x.email)}</small></td><td>${E(x.plan_code)}</td><td><b>${x.impact_score||0}/100</b><div class="pc15-progress"><span style="width:${Math.max(0,Math.min(100,Number(x.impact_score||0)))}%"></span></div></td><td>${statusBadge(x.adoption_status)}</td><td>${D(x.plan_ends_at)}</td><td>${D(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aún no tienes clientes atribuidos','Comparte tu enlace inteligente o trabaja prospectos desde Sell.')}`;
    $('#pc15CRM')?.addEventListener('click',()=>switchMainView('contacts'));
  }

  async function renderCommissions(c){
    const d=await request('/api/partners/ledger'), xs=d.items||[],b=d.balances||{};
    c.innerHTML=`${topbar('Comisiones','Libro mayor auditable: cada movimiento conserva su origen, porcentaje, estado y fecha.',`<button class="pc15-btn" data-go-payouts>Solicitar payout</button>`)}<div class="pc15-grid pc15-balances"><div class="pc15-card pc15-balance available"><small>Disponible</small><b>${M(b.available)}</b></div><div class="pc15-card pc15-balance pending"><small>Pendiente</small><b>${M(b.pending)}</b></div><div class="pc15-card pc15-balance"><small>Reservado</small><b>${M(b.reserved)}</b></div><div class="pc15-card pc15-balance"><small>Ganado histórico</small><b>${M(b.earned)}</b></div></div>${xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Concepto</th><th>Cliente</th><th>Base</th><th>%</th><th>Movimiento</th><th>Estado</th><th>Disponible</th><th>Creado</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(commissionLabel(x.commission_type))}${x.level>1?` · N${x.level}`:''}</b><small>${x.payment_id?`Pago #${x.payment_id}`:''}</small></td><td>${E(x.customer_name||'—')}</td><td>${M(x.eligible_base)}</td><td>${Number(x.percent||0)}%</td><td><b>${Number(x.amount||0)<0?'-':''}${M(Math.abs(Number(x.amount||0)))}</b></td><td>${statusBadge(x.status)}</td><td>${D(x.available_at)}</td><td>${D(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay movimientos','Las ventas aprobadas, adopción, red, mentoría y Human Sales aparecerán aquí.')}`;
    $('[data-go-payouts]')?.addEventListener('click',()=>openView('payouts'));
  }

  function renderMomentum(c){
    const o=state.overview||{},p=o.profile||{},s=o.stats||{},current=p.rank_code||'spark';const currentOrder=state.ranks.find(r=>r.code===current)?.sort_order||1;const next=state.ranks.find(r=>r.sort_order===currentOrder+1);const direct=s.direct_active||0,adopted=s.adopted_active||0;
    const pd=next?Math.min(100,direct/Math.max(1,next.min_direct_active)*100):100,pa=next?Math.min(100,adopted/Math.max(1,next.min_adopted)*100):100;
    c.innerHTML=`${topbar('Worktic Momentum','Tu rango se calcula por clientes activos y adopción real. La protección evita descensos inmediatos.')}`+`<div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Rango actual · ${E(p.rank_name||current)}</h3><p>${next?`Siguiente objetivo: ${E(next.name)}`:'Has alcanzado el rango superior.'}</p></div><span class="pc15-rank-pill">${Number(state.ranks.find(r=>r.code===current)?.direct_percent||0)}% directa</span></div>${next?`<p>Clientes activos · <b>${direct}/${next.min_direct_active}</b></p><div class="pc15-progress"><span style="width:${pd}%"></span></div><p style="margin-top:12px">Clientes con adopción · <b>${adopted}/${next.min_adopted}</b></p><div class="pc15-progress"><span style="width:${pa}%"></span></div>`:'<p>Continúa consolidando cartera, adopción y liderazgo.</p>'}</section><section class="pc15-card"><h3>Bonos conectados</h3><p>Además de la comisión directa: adopción certificada, renovación, N2/N3 según rango y mentoría automática cuando corresponde.</p><div style="margin-top:12px;display:grid;gap:7px"><span class="pc15-badge good">Adopción 4% elegible</span><span class="pc15-badge">Renovación 2% elegible</span><span class="pc15-badge">Mentoría 2% elegible</span></div></section></div><div class="pc15-rank-track">${state.ranks.map(r=>`<div class="pc15-rank-node ${r.code===current?'active':r.sort_order<currentOrder?'done':''}"><b>${E(r.name)}</b><strong>${r.direct_percent}%</strong><small>${r.min_direct_active} clientes · ${r.min_adopted} adopción${r.level2_percent?` · N2 ${r.level2_percent}%`:''}${r.level3_percent?` · N3 ${r.level3_percent}%`:''}</small></div>`).join('')}</div>`;
  }

  async function renderCosell(c){
    const xs=await request('/api/partners/cosell');
    c.innerHTML=`${topbar('Worktic Co-Sell','Comparte una comisión directa entre quien aporta el prospecto y quien realiza la demo/cierre.')}`+`<div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Nuevo acuerdo Co-Sell</h3><p>La otra persona debe aceptar antes de que el acuerdo quede activo.</p></div></div><div class="pc15-form"><div class="pc15-form-grid"><label>Código del otro Partner<input id="csPartner" placeholder="WTXXXXXX"></label><label>Mi rol<select id="csRole"><option value="referrer">Referidor</option><option value="closer">Asesor / closer</option></select></label><label>Prospecto<input id="csName" placeholder="Empresa o persona"></label><label>Correo del prospecto<input id="csEmail" type="email" placeholder="cliente@empresa.com"></label><label>Reparto del referidor (%)<input id="csSplit" type="number" min="10" max="90" value="70"></label><label>ID oportunidad CRM (opcional)<input id="csOpp" type="number" min="0"></label></div><label>Nota<textarea id="csNote" placeholder="Contexto del prospecto y acuerdo"></textarea></label><div class="pc15-form-actions"><button class="pc15-btn" id="csCreate">Proponer Co-Sell</button></div></div></section><section class="pc15-card"><h3>Cómo se protege el acuerdo</h3><p>El creador acepta su parte al proponerlo. La otra parte debe aceptar. Solo entonces queda activo. Cuando una venta atribuida al referidor es aprobada, la comisión directa se divide según el acuerdo y queda registrada en el ledger.</p><div class="pc15-grid pc15-three" style="margin-top:12px"><div class="pc15-kpi"><small>Abiertos</small><b>${xs.filter(x=>['pending','active'].includes(x.status)).length}</b></div><div class="pc15-kpi"><small>Ganados</small><b>${xs.filter(x=>x.status==='won').length}</b></div><div class="pc15-kpi"><small>Default</small><b>70/30</b></div></div></section></div>`+`${xs.length?`<div class="pc15-card" style="margin-top:13px"><div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Prospecto</th><th>Referidor</th><th>Closer</th><th>Reparto</th><th>Aceptación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.prospect_name||'—')}</b><small>${E(x.prospect_email||'')}</small></td><td>${E(x.referrer_name)}</td><td>${E(x.closer_name)}</td><td>${x.referrer_split}% / ${x.closer_split}%</td><td><small>Referidor ${x.referrer_accepted?'✓':'…'} · Closer ${x.closer_accepted?'✓':'…'}</small></td><td>${statusBadge(x.status)}</td><td><div class="pc15-top-actions">${x.status==='pending'?`<button class="pc15-btn good" data-cs-accept="${x.id}">Aceptar</button><button class="pc15-btn danger" data-cs-reject="${x.id}">Rechazar</button>`:''}${x.status==='active'&&x.my_role==='referrer'?`<button class="pc15-btn danger" data-cs-cancel="${x.id}">Cancelar</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>`:''}`;
    $('#csCreate')?.addEventListener('click',async e=>{const b=e.currentTarget;setBusy(b);try{await request('/api/partners/cosell',{method:'POST',body:JSON.stringify({other_partner_code:$('#csPartner').value,my_role:$('#csRole').value,prospect_name:$('#csName').value,prospect_email:$('#csEmail').value,referrer_split:Number($('#csSplit').value),crm_opportunity_id:Number($('#csOpp').value||0),note:$('#csNote').value})});notify('Propuesta Co-Sell creada');renderCosell(c)}catch(err){notify(err.message)}finally{unBusy(b)}});
    $$('[data-cs-accept]').forEach(b=>b.onclick=()=>cosellAction(c,b.dataset.csAccept,'accept'));$$('[data-cs-reject]').forEach(b=>b.onclick=()=>cosellAction(c,b.dataset.csReject,'reject'));$$('[data-cs-cancel]').forEach(b=>b.onclick=()=>cosellAction(c,b.dataset.csCancel,'cancel'));
  }
  async function cosellAction(c,id,action){try{await request('/api/partners/cosell',{method:'PUT',body:JSON.stringify({id:Number(id),action})});notify('Co-Sell actualizado');renderCosell(c)}catch(e){notify(e.message)}}

  async function renderActivate(c){
    const d=await request('/api/partners/certification'), status=d.activate_status||'not_certified', item=(d.items||[])[0];
    c.innerHTML=`${topbar('Activate Certified','Certificación profesional para implementar WorkticAI y acceder a Human Sales.',`<button class="pc15-btn" id="pc15Academy">Ir a Academy</button>`)}<div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Estado de certificación</h3><p>Academy comunica automáticamente el resultado al Partner Center mediante evento firmado.</p></div>${statusBadge(status)}</div>${item?`<div class="pc15-grid pc15-three"><div class="pc15-kpi"><small>Examen</small><b style="font-size:13px">${E(item.exam_code)}</b></div><div class="pc15-kpi"><small>Nota</small><b>${Number(item.score||0)}</b><em>Mínimo ${Number(item.passing_score||0)}</em></div><div class="pc15-kpi"><small>Emitido</small><b style="font-size:13px">${D(item.issued_at)}</b></div></div>${item.certificate_url?`<a class="pc15-btn secondary" href="${E(item.certificate_url)}" target="_blank" rel="noopener" style="display:inline-flex;text-decoration:none;margin-top:12px">Ver certificado</a>`:''}`:`${empty('Aún no estás certificado','Completa la ruta Activate Certified y aprueba el examen en WorkticAI Academy.')}`}</section><section class="pc15-card"><h3>Qué desbloquea Activate Certified</h3><p>Implementaciones, asignación de clientes para adopción, acceso al marketplace Human Sales y posibilidad de trabajar oportunidades comerciales de empresas dentro de WorkticAI.</p><div style="margin-top:12px;display:grid;gap:7px"><span class="pc15-badge good">Implementación CRM + canales + automatización</span><span class="pc15-badge good">Impact Score y adopción</span><span class="pc15-badge good">Human Sales · 80% especialista / 20% WorkticAI</span></div></section></div>`;
    $('#pc15Academy')?.addEventListener('click',()=>window.open(d.academy_url||'https://academy.workticai.com','_blank'));
  }

  async function renderMarketplace(c){
    const [jobs,apps,sales]=await Promise.all([request('/api/partners/marketplace/jobs'),request('/api/partners/marketplace/applications'),request('/api/partners/marketplace/sales')]);
    const cert=(state.overview?.certification?.status==='certified'||state.overview?.profile?.activate_status==='certified');
    c.innerHTML=`${topbar('Human Sales Network','Empresas publican oportunidades comerciales y especialistas certificados venden usando WorkticAI.')}`+`<div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Oportunidades disponibles</h3><p>El 80/20 se aplica sobre la comisión comercial pactada, no sobre la venta completa.</p></div><span class="pc15-badge ${cert?'good':'warn'}">${cert?'Activate Certified':'Certificación requerida'}</span></div><div class="pc15-job-grid">${jobs.filter(j=>j.status==='open').map(j=>`<article class="pc15-job"><h4>${E(j.title)}</h4><p>${E(j.business_name)} · ${E(j.region||'Remoto')}</p><div class="pc15-job-meta"><span class="pc15-badge">${Number(j.commission_percent)}% comisión comercial</span><span class="pc15-badge">${E(j.modality)}</span><span class="pc15-badge">${j.accepted||0}/${j.slots} asignados</span></div><p>${E(j.description||j.product_service||'')}</p>${j.owned_by_me?'':`<div class="pc15-job-actions"><button class="pc15-btn ${cert?'':'secondary'}" data-job-apply="${j.id}" ${cert?'':'disabled'}>Aplicar</button></div>`}</article>`).join('')||empty('No hay oportunidades abiertas','Las empresas aprobadas aparecerán aquí.')}</div></section><section class="pc15-card"><div class="pc15-card-head"><div><h3>Publicar oportunidad</h3><p>Disponible para cuentas Empresa. Toda publicación pasa por revisión administrativa.</p></div></div><div class="pc15-form"><label>Título<input id="jobTitle" placeholder="Ej. Ejecutivo comercial SaaS"></label><label>Producto / servicio<input id="jobProduct" placeholder="Software empresarial, consultoría…"></label><div class="pc15-form-grid"><label>Comisión sobre venta (%)<input id="jobPct" type="number" min="0.1" max="50" step="0.1" value="10"></label><label>Cupos<input id="jobSlots" type="number" min="1" max="100" value="1"></label><label>Región<input id="jobRegion" placeholder="Colombia / LATAM"></label><label>Modalidad<select id="jobModality"><option value="remote">Remoto</option><option value="hybrid">Híbrido</option><option value="onsite">Presencial</option></select></label></div><label>Descripción<textarea id="jobDesc"></textarea></label><label>Requisitos<textarea id="jobReq" placeholder="Activate Certified, experiencia…"></textarea></label><div class="pc15-form-actions"><button class="pc15-btn" id="jobCreate">Enviar a revisión</button></div></div></section></div>`+
      `<section class="pc15-card" style="margin-top:13px"><div class="pc15-card-head"><div><h3>Aplicaciones y asignaciones</h3><p>Especialistas y empresas ven el mismo flujo de aceptación.</p></div></div>${apps.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Oportunidad</th><th>Especialista</th><th>Empresa</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${apps.map(a=>`<tr><td>${E(a.job_title)}</td><td><b>${E(a.specialist_name)}</b><small>${E(a.specialist_email)}</small></td><td>${E(a.business_name)}</td><td>${statusBadge(a.status)}</td><td><div class="pc15-top-actions">${a.is_business&&a.status==='applied'?`<button class="pc15-btn good" data-app-accept="${a.id}">Aceptar</button><button class="pc15-btn danger" data-app-reject="${a.id}">Rechazar</button>`:''}${a.is_mine&&a.status==='applied'?`<button class="pc15-btn danger" data-app-withdraw="${a.id}">Retirar</button>`:''}${a.is_mine&&a.status==='accepted'?`<button class="pc15-btn" data-sale-report="${a.id}">Reportar venta</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Aún no hay aplicaciones','Aplica a una oportunidad o publica una para recibir especialistas.')}</section>`+
      `<section class="pc15-card" style="margin-top:13px"><div class="pc15-card-head"><div><h3>Ventas Human Sales</h3><p>La venta la reporta el especialista, la confirma la empresa y WorkticAI valida el settlement antes de liberar la comisión.</p></div></div>${sales.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Venta</th><th>Especialista</th><th>Monto</th><th>Pool</th><th>Especialista 80%</th><th>WorkticAI 20%</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${sales.map(s=>`<tr><td><b>${E(s.customer_name||s.job_title)}</b><small>${E(s.external_reference||s.job_title)}</small></td><td>${E(s.specialist_name)}</td><td>${M(s.gross_sale_amount)}</td><td>${M(s.commission_pool)}</td><td><b>${M(s.specialist_amount)}</b></td><td>${M(s.platform_amount)}</td><td>${statusBadge(s.status)}</td><td>${s.is_business&&s.status==='reported'?`<div class="pc15-top-actions"><button class="pc15-btn good" data-sale-confirm="${s.id}">Confirmar</button><button class="pc15-btn danger" data-sale-reject="${s.id}">Rechazar</button></div>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin ventas reportadas','Las ventas Human Sales se mostrarán aquí con su reparto completo.')}</section>`;
    $$('[data-job-apply]').forEach(b=>b.onclick=async()=>{const message=prompt('Mensaje para la empresa (opcional):','Estoy interesado en esta oportunidad y cuento con Activate Certified.')||'';try{await request('/api/partners/marketplace/applications',{method:'POST',body:JSON.stringify({job_id:Number(b.dataset.jobApply),message})});notify('Aplicación enviada');renderMarketplace(c)}catch(e){notify(e.message)}});
    $('#jobCreate')?.addEventListener('click',async e=>{const b=e.currentTarget;setBusy(b);try{await request('/api/partners/marketplace/jobs',{method:'POST',body:JSON.stringify({title:$('#jobTitle').value,product_service:$('#jobProduct').value,description:$('#jobDesc').value,region:$('#jobRegion').value,modality:$('#jobModality').value,commission_percent:Number($('#jobPct').value),currency:'USD',leads_source:'business',requirements:$('#jobReq').value,slots:Number($('#jobSlots').value)})});notify('Oportunidad enviada a revisión');renderMarketplace(c)}catch(err){notify(err.message)}finally{unBusy(b)}});
    const appAction=(id,action)=>request('/api/partners/marketplace/applications',{method:'PUT',body:JSON.stringify({id:Number(id),action})}).then(()=>{notify('Aplicación actualizada');renderMarketplace(c)}).catch(e=>notify(e.message));
    $$('[data-app-accept]').forEach(b=>b.onclick=()=>appAction(b.dataset.appAccept,'accept'));$$('[data-app-reject]').forEach(b=>b.onclick=()=>appAction(b.dataset.appReject,'reject'));$$('[data-app-withdraw]').forEach(b=>b.onclick=()=>appAction(b.dataset.appWithdraw,'withdraw'));
    $$('[data-sale-report]').forEach(b=>b.onclick=async()=>{const amount=Number(prompt('Monto total de la venta en USD:','1000')||0);if(!amount)return;const customer_name=prompt('Cliente / empresa compradora:','')||'';const external_reference=prompt('Referencia de venta (opcional):','')||'';try{const d=await request('/api/partners/marketplace/sales',{method:'POST',body:JSON.stringify({application_id:Number(b.dataset.saleReport),gross_sale_amount:amount,customer_name,external_reference})});notify(`Venta reportada. Tu parte estimada: ${M(d.specialist_amount)}`);renderMarketplace(c)}catch(e){notify(e.message)}});
    const saleAction=(id,action)=>request('/api/partners/marketplace/sales',{method:'PUT',body:JSON.stringify({id:Number(id),action,note:''})}).then(()=>{notify('Venta actualizada');renderMarketplace(c)}).catch(e=>notify(e.message));
    $$('[data-sale-confirm]').forEach(b=>b.onclick=()=>saleAction(b.dataset.saleConfirm,'confirm'));$$('[data-sale-reject]').forEach(b=>b.onclick=()=>saleAction(b.dataset.saleReject,'reject'));
  }

  async function renderPayouts(c){
    const d=await request('/api/partners/payouts'),b=d.balances||{},p=d.profile||{},xs=d.items||[];
    c.innerHTML=`${topbar('Payouts','Configura tu destino, solicita fondos disponibles y sigue el estado hasta el pago.')}`+`<div class="pc15-grid pc15-balances"><div class="pc15-card pc15-balance available"><small>Disponible</small><b>${M(b.available)}</b></div><div class="pc15-card pc15-balance"><small>Reservado</small><b>${M(b.reserved)}</b></div><div class="pc15-card pc15-balance"><small>Pagado</small><b>${M(b.paid)}</b></div><div class="pc15-card pc15-balance"><small>Retiro mínimo</small><b>${M(d.minimum)}</b></div></div><div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Método de pago</h3><p>Guarda el destino que usaremos para futuras solicitudes.</p></div></div><div class="pc15-form"><div class="pc15-form-grid"><label>Método<select id="poMethod"><option ${p.method==='USDT_TRC20'?'selected':''}>USDT_TRC20</option><option ${p.method==='USDT_BEP20'?'selected':''}>USDT_BEP20</option><option ${p.method==='BANK'?'selected':''}>BANK</option></select></label><label>País<input id="poCountry" value="${E(p.country||'')}"></label></div><label>Destino / wallet / cuenta<input id="poDest" value="${E(p.destination||'')}"></label><label>Titular<input id="poHolder" value="${E(p.holder_name||'')}"></label><div class="pc15-form-actions"><button class="pc15-btn secondary" id="poSave">Guardar método</button></div></div></section><section class="pc15-card"><div class="pc15-card-head"><div><h3>Solicitar payout</h3><p>El monto se reserva durante revisión y deja de estar disponible para una segunda solicitud.</p></div></div><div class="pc15-form"><label>Monto USD<input id="poAmount" type="number" min="${Number(d.minimum||20)}" max="${Number(b.available||0)}" step="0.01" value="${Math.max(Number(d.minimum||20),Math.min(Number(b.available||0),Number(d.minimum||20))).toFixed(2)}"></label><div class="pc15-form-actions"><button class="pc15-btn" id="poRequest" ${Number(b.available||0)<Number(d.minimum||20)?'disabled':''}>Solicitar payout</button></div></div></section></div>`+`${xs.length?`<section class="pc15-card" style="margin-top:13px"><div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Solicitud</th><th>Monto</th><th>Método</th><th>Destino</th><th>Estado</th><th>Referencia</th><th>Fecha</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td>#${x.id}</td><td><b>${M(x.amount)}</b></td><td>${E(x.method)}</td><td>${E(x.destination)}</td><td>${statusBadge(x.status)}</td><td>${E(x.reference||'—')}</td><td>${D(x.requested_at)}</td><td>${x.status==='requested'?`<button class="pc15-btn danger" data-po-cancel="${x.id}">Cancelar</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;
    $('#poSave')?.addEventListener('click',async()=>{try{await request('/api/partners/payouts',{method:'POST',body:JSON.stringify({action:'profile',method:$('#poMethod').value,destination:$('#poDest').value,holder_name:$('#poHolder').value,country:$('#poCountry').value})});notify('Método de payout guardado')}catch(e){notify(e.message)}});
    $('#poRequest')?.addEventListener('click',async()=>{try{await request('/api/partners/payouts',{method:'POST',body:JSON.stringify({action:'request',amount:Number($('#poAmount').value)})});notify('Payout solicitado');renderPayouts(c)}catch(e){notify(e.message)}});
    $$('[data-po-cancel]').forEach(b=>b.onclick=async()=>{try{await request('/api/partners/payouts',{method:'PUT',body:JSON.stringify({id:Number(b.dataset.poCancel)})});notify('Payout cancelado');renderPayouts(c)}catch(e){notify(e.message)}});
  }

  async function renderAutopilot(c){
    const plans=await request('/api/partners/autopilot'); const latest=plans[0]||null; state.lastAutopilot=latest;
    c.innerHTML=`${topbar('Partner Autopilot','WorkticAI te ayuda a vender WorkticAI con una estrategia conectada a Growth, Landing Pages y tu enlace atribuido.')}`+`<div class="pc15-grid pc15-two"><section class="pc15-card"><div class="pc15-card-head"><div><h3>Crear plan comercial</h3><p>Define el mercado; Copilot prepara posicionamiento, mensajes, seguimiento, contenido, demo y pipeline.</p></div></div><div class="pc15-form"><label>Nicho<input id="apNiche" placeholder="Ej. restaurantes, clínicas, inmobiliarias"></label><label>Objetivo<input id="apGoal" placeholder="Ej. conseguir mis primeros 3 clientes"></label><div class="pc15-form-grid"><label>Meta de clientes<input id="apTarget" type="number" min="1" max="100" value="3"></label><label>Canal principal<select id="apChannel"><option value="mixed">Multicanal</option><option value="whatsapp">WhatsApp</option><option value="social">Social</option><option value="email">Email</option></select></label></div><label>Oferta / ángulo<textarea id="apOffer" placeholder="Qué problema resolverás y para quién"></textarea></label><div class="pc15-form-actions"><button class="pc15-btn" id="apGenerate">Generar con IA</button></div></div></section><section class="pc15-card"><h3>Activación real</h3><p>Cuando apruebes el plan, Autopilot puede crear un borrador de campaña Growth, piezas de contenido y una Landing Page con tu enlace Partner. Nada se publica automáticamente.</p><div style="margin-top:12px;display:grid;gap:7px"><span class="pc15-badge good">CRM y pipeline</span><span class="pc15-badge good">Growth & Campañas</span><span class="pc15-badge good">Landing con atribución</span><span class="pc15-badge">Publicación bajo tu control</span></div></section></div><div id="apResult" style="margin-top:13px">${latest?planHTML(latest):empty('Aún no hay planes Autopilot','Genera tu primera estrategia para un nicho específico.')}</div>`;
    $('#apGenerate')?.addEventListener('click',async e=>{const b=e.currentTarget;setBusy(b,'Generando…');try{const d=await request('/api/partners/autopilot',{method:'POST',body:JSON.stringify({niche:$('#apNiche').value,goal:$('#apGoal').value,target_clients:Number($('#apTarget').value),offer:$('#apOffer').value,primary_channel:$('#apChannel').value})});notify('Plan Autopilot generado');await renderAutopilot(c)}catch(err){notify(err.message)}finally{unBusy(b)}});
    bindAutopilotActivate(c);
  }
  function planHTML(x){const p=x.plan||{};const arr=(k)=>Array.isArray(p[k])?p[k]:[];return `<section class="pc15-autopilot-plan"><div class="pc15-card-head"><div><h3>${E(x.niche||'Plan Partner')}</h3><p>${E(x.goal||'')}</p></div>${statusBadge(x.status)}</div><div class="pc15-plan-section"><h4>Posicionamiento</h4><p>${E(p.positioning||'—')}</p></div><div class="pc15-plan-section"><h4>Cliente ideal</h4><p>${E(p.ideal_customer||'—')}</p></div><div class="pc15-plan-section"><h4>Landing</h4><p><b>${E(p.landing_headline||'')}</b><br>${E(p.landing_subheadline||'')}</p></div><div class="pc15-grid pc15-two"><div class="pc15-plan-section"><h4>Mensajes</h4><ul>${arr('outreach_messages').map(v=>`<li>${E(v)}</li>`).join('')}</ul></div><div class="pc15-plan-section"><h4>Seguimientos</h4><ul>${arr('followups').map(v=>`<li>${E(v)}</li>`).join('')}</ul></div></div><div class="pc15-plan-section"><h4>Acciones semanales</h4><ul>${arr('weekly_actions').map(v=>`<li>${E(v)}</li>`).join('')}</ul></div><div class="pc15-top-actions" style="margin-top:12px">${x.status==='activated'?`<button class="pc15-btn secondary" data-open-main="marketing">Abrir Growth</button><button class="pc15-btn secondary" data-open-main="landings">Abrir Landing Pages</button>`:`<button class="pc15-btn" data-ap-activate="${x.id}">Crear borradores en WorkticAI</button>`}</div></section>`}
  function bindAutopilotActivate(c){$$('[data-ap-activate]').forEach(b=>b.onclick=async()=>{setBusy(b);try{await request('/api/partners/autopilot/activate',{method:'POST',body:JSON.stringify({plan_id:Number(b.dataset.apActivate)})});notify('Borradores creados en Growth y Landing Pages');renderAutopilot(c)}catch(e){notify(e.message)}finally{unBusy(b)}});$$('[data-open-main]').forEach(b=>b.onclick=()=>switchMainView(b.dataset.openMain))}

  function renderSettings(c){
    const o=state.overview||{},p=o.profile||{};
    c.innerHTML=`${topbar('Configuración Partner','Identidad, atribución y accesos conectados a tu cuenta WorkticAI.')}`+`<div class="pc15-grid pc15-two"><section class="pc15-card"><h3>Identidad Partner</h3><div class="pc15-table-wrap" style="margin-top:10px"><table class="pc15-table"><tbody><tr><th>Código</th><td><b>${E(p.partner_code||'—')}</b></td></tr><tr><th>Rango</th><td>${E(p.rank_name||p.rank_code||'—')}</td></tr><tr><th>Licencia</th><td>${E(o.plan_code||'—')} · ${o.plan_ends_at?`hasta ${D(o.plan_ends_at)}`:'—'}</td></tr><tr><th>Estado</th><td>${statusBadge(p.status||'active')}</td></tr><tr><th>Activate</th><td>${statusBadge(p.activate_status)}</td></tr></tbody></table></div></section><section class="pc15-card"><h3>Enlace de atribución</h3><p>Úsalo en campañas, contenido, mensajes y landings para conservar el origen del cliente.</p><div class="pc15-ref" style="margin-top:12px"><input id="pc15SettingsRef" readonly value="${E(o.referral_url||'')}"><button class="pc15-btn secondary" id="pc15SettingsCopy">Copiar</button></div><div class="pc15-top-actions" style="margin-top:12px"><button class="pc15-btn secondary" id="pc15SettingsPublic">Programa público</button><button class="pc15-btn secondary" id="pc15SettingsAcademy">Academy</button></div></section></div>`;
    $('#pc15SettingsCopy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#pc15SettingsRef').value);notify('Enlace copiado')}catch{}});$('#pc15SettingsPublic')?.addEventListener('click',()=>window.open('/partners.html','_blank'));$('#pc15SettingsAcademy')?.addEventListener('click',()=>window.open('https://academy.workticai.com','_blank'));
  }

  function switchMainView(v){const b=document.querySelector(`nav button[data-view="${v}"]`);if(b)b.click()}

  async function loadPartnersV2715(force=false){
    const root=$('#partnerscenter'); if(!root)return;
    if(force) root.innerHTML='<div class="pc15-loading">Actualizando Partner Center…</div>';
    try{const d=await loadBase();if(!d.active){root.innerHTML=activationScreen(d);$('#pc15Activate')?.addEventListener('click',async e=>{setBusy(e.currentTarget,'Activando…');try{await request('/api/partners/me',{method:'POST',body:'{}'});notify('Partner Center activado');loadPartnersV2715(true)}catch(err){notify(err.message)}finally{unBusy(e.currentTarget)}});$('#pc15GoBilling')?.addEventListener('click',()=>switchMainView('billing'));return;}if(d.suspended){root.innerHTML=`<div class="pc15-activate-screen"><span class="pc15-eyebrow">WORKTIC PARTNERS</span><h2>Partner Center suspendido</h2><p>Tu historial permanece protegido. El administrador debe revisar el estado de tu perfil Partner.</p></div>`;return;}root.innerHTML=shell();bindWorkspaceControls();bindNav();openView(state.view||'home')}catch(e){root.innerHTML=empty('No fue posible iniciar Partner Center',e.message||'Intenta nuevamente.')}
  }
  window.loadPartnersV2715=loadPartnersV2715;

  // Workspace lifecycle: Partner Center collapses the CRM shell on desktop and restores it on exit.
  $$('#appSidebar nav button[data-view]').forEach(b=>b.addEventListener('click',()=>{
    const active=b.dataset.view==='partnerscenter';
    setPartnerWorkspace(active);
  }));
  document.addEventListener('fullscreenchange',syncWorkspaceButtons);
  window.addEventListener('resize',()=>{if(window.innerWidth>900)closePartnerDrawer()});

  /* ============================ SUPERADMIN PARTNERS ============================ */
  const adminState={tab:'overview',partners:null};
  function adminRoot(){return $('#wtAdminPartnerRoot')}
  const adminTabs=[['overview','Resumen'],['partners','Partners'],['adoption','Adopción'],['cosell','Co-Sell'],['marketplace','Human Sales'],['payouts','Payouts'],['certifications','Certificaciones'],['settings','Configuración']];
  function adminShell(summary){return `<article class="wt-admin-card"><div class="pa15-head"><div><h3>Worktic Partners · Business Operations</h3><p>Control central de red, dinero, certificación, Co-Sell, Human Sales y reglas del programa.</p></div><a class="secondary" href="/partners.html" target="_blank" rel="noopener" style="text-decoration:none;padding:9px 12px;border-radius:10px">Ver landing</a></div><div class="pa15-summary" style="margin-top:14px"><div><b>${summary.partners||0}</b><small>Partners</small></div><div><b>${summary.active||0}</b><small>Activos</small></div><div><b>${summary.certified||0}</b><small>Certificados</small></div><div><b>${summary.jobs_open||0}</b><small>Human Sales</small></div><div><b>${summary.payouts_pending||0}</b><small>Payouts pendientes</small></div><div><b>${M(summary.commissions_generated)}</b><small>Comisiones</small></div></div><div class="pa15-tabs" style="margin-top:14px">${adminTabs.map(([id,n])=>`<button type="button" data-pa15-tab="${id}" class="${id===adminState.tab?'active':''}">${n}</button>`).join('')}</div><div class="pa15-body" id="pa15Body" style="margin-top:14px"></div></article>`}
  async function loadPartnerAdminV2715(){const root=adminRoot();if(!root)return;try{const summary=await request('/api/admin/partners/dashboard');root.innerHTML=adminShell(summary);$$('[data-pa15-tab]').forEach(b=>b.onclick=()=>openAdminTab(b.dataset.pa15Tab));openAdminTab(adminState.tab)}catch(e){root.innerHTML=`<article class="wt-admin-card">${empty('No fue posible cargar Worktic Partners',e.message)}</article>`}}
  window.loadPartnerAdminV2715=loadPartnerAdminV2715;
  async function openAdminTab(tab){adminState.tab=tab;$$('[data-pa15-tab]').forEach(b=>b.classList.toggle('active',b.dataset.pa15Tab===tab));const el=$('#pa15Body');if(!el)return;el.innerHTML='<div class="pc15-loading">Cargando…</div>';try{if(tab==='overview')return adminOverview(el);if(tab==='partners')return adminPartners(el);if(tab==='adoption')return adminAdoption(el);if(tab==='cosell')return adminCosell(el);if(tab==='marketplace')return adminMarketplace(el);if(tab==='payouts')return adminPayouts(el);if(tab==='certifications')return adminCertifications(el);if(tab==='settings')return adminSettings(el)}catch(e){el.innerHTML=empty('Error al cargar',e.message)}}
  async function adminOverview(el){const [d,p]=await Promise.all([request('/api/admin/partners/dashboard'),request('/api/admin/partners')]);adminState.partners=p;el.innerHTML=`<div class="pc15-grid pc15-three"><div class="pc15-card"><h3>Comisiones generadas</h3><b style="font-size:24px">${M(d.commissions_generated)}</b><p>Ledger total positivo no reversado.</p></div><div class="pc15-card"><h3>Payouts pagados</h3><b style="font-size:24px">${M(d.payouts_paid)}</b><p>Histórico ejecutado por administración.</p></div><div class="pc15-card"><h3>Ingreso Human Sales</h3><b style="font-size:24px">${M(d.human_sales_platform_revenue)}</b><p>Parte WorkticAI de ventas aprobadas.</p></div></div><div class="pc15-card" style="margin-top:12px"><h3>Estado operativo</h3><p>${d.cosell_open||0} Co-Sell abiertos · ${d.jobs_open||0} oportunidades Human Sales · ${d.certified||0} especialistas Activate Certified · ${d.payouts_pending||0} payouts esperando gestión.</p></div>`}
  async function adminPartners(el){const d=await request('/api/admin/partners');adminState.partners=d;const xs=d.items||[];el.innerHTML=xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Partner</th><th>Código</th><th>Rango</th><th>Clientes / adopción</th><th>Red</th><th>Comisiones</th><th>Activate</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.name)}</b><small>${E(x.email)}</small></td><td>${E(x.partner_code)}</td><td>${E(x.rank_code)}</td><td>${x.direct_active} / ${x.adopted_active}</td><td>N2 ${x.level2_partners} · N3 ${x.level3_partners}</td><td><small>P ${M(x.pending)} · D ${M(x.available)} · Pag ${M(x.paid)}</small></td><td>${statusBadge(x.activate_status)}</td><td>${statusBadge(x.status)}</td><td><div class="pa15-inline"><button class="pc15-btn secondary" data-pa-rank="${x.user_id}">Reevaluar</button><button class="pc15-btn ${x.status==='active'?'danger':'good'}" data-pa-status="${x.user_id}" data-status="${x.status==='active'?'suspended':'active'}">${x.status==='active'?'Suspender':'Reactivar'}</button><button class="pc15-btn secondary" data-pa-cert="${x.user_id}">${x.activate_status==='certified'?'Revocar cert.':'Certificar'}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No hay Partners','');$$('[data-pa-rank]').forEach(b=>b.onclick=()=>adminPartnerAction(Number(b.dataset.paRank),{action:'reevaluate_rank'}));$$('[data-pa-status]').forEach(b=>b.onclick=()=>adminPartnerAction(Number(b.dataset.paStatus),{action:'status',status:b.dataset.status}));$$('[data-pa-cert]').forEach(b=>b.onclick=async()=>{const uid=Number(b.dataset.paCert),x=xs.find(v=>v.user_id===uid),action=x?.activate_status==='certified'?'revoke':'certify';try{await request('/api/admin/partners/certifications',{method:'PUT',body:JSON.stringify({user_id:uid,action,score:100,passing_score:80})});notify('Certificación actualizada');adminPartners(el)}catch(e){notify(e.message)}})}
  async function adminPartnerAction(uid,data){try{await request('/api/admin/partners',{method:'PUT',body:JSON.stringify({user_id:uid,...data})});notify('Partner actualizado');openAdminTab('partners')}catch(e){notify(e.message)}}
  async function adminAdoption(el){const [xs,pd]=await Promise.all([request('/api/admin/partners/adoption'),request('/api/admin/partners')]);const cert=(pd.items||[]).filter(x=>x.activate_status==='certified'&&x.status==='active');el.innerHTML=xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Cliente</th><th>Origen</th><th>Especialista</th><th>Impact Score</th><th>Estado</th><th>Guardar</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.customer_name)}</b><small>${E(x.customer_email)}</small></td><td>${E(x.origin_partner_name)}</td><td><select data-ad-spec="${x.customer_user_id}"><option value="0">Sin asignar</option>${cert.map(p=>`<option value="${p.user_id}" ${p.user_id===x.specialist_partner_user_id?'selected':''}>${E(p.name)}</option>`).join('')}</select></td><td><input data-ad-score="${x.customer_user_id}" type="number" min="0" max="100" value="${x.impact_score||0}" style="width:75px"></td><td><select data-ad-status="${x.customer_user_id}"><option value="pending" ${x.status==='pending'?'selected':''}>Pendiente</option><option value="approved" ${x.status==='approved'?'selected':''}>Aprobado</option><option value="rejected" ${x.status==='rejected'?'selected':''}>Rechazado</option></select></td><td><button class="pc15-btn secondary" data-ad-save="${x.customer_user_id}">Guardar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Sin clientes atribuidos','');$$('[data-ad-save]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.adSave);try{await request('/api/admin/partners/adoption',{method:'PUT',body:JSON.stringify({customer_user_id:id,specialist_partner_user_id:Number($(`[data-ad-spec="${id}"]`).value),impact_score:Number($(`[data-ad-score="${id}"]`).value),status:$(`[data-ad-status="${id}"]`).value})});notify('Adopción actualizada')}catch(e){notify(e.message)}})}
  async function adminCosell(el){const xs=await request('/api/admin/partners/cosell');el.innerHTML=xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>ID</th><th>Prospecto</th><th>Referidor</th><th>Closer</th><th>Split</th><th>Aceptación</th><th>Estado</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td>#${x.id}</td><td><b>${E(x.prospect_name)}</b><small>${E(x.prospect_email)}</small></td><td>${E(x.referrer_name)}</td><td>${E(x.closer_name)}</td><td>${x.referrer_split}/${x.closer_split}</td><td>${x.referrer_accepted?'R ✓':'R …'} · ${x.closer_accepted?'C ✓':'C …'}</td><td>${statusBadge(x.status)}</td><td>${!['won','cancelled'].includes(x.status)?`<button class="pc15-btn danger" data-acs-cancel="${x.id}">Cancelar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin acuerdos Co-Sell','');$$('[data-acs-cancel]').forEach(b=>b.onclick=async()=>{try{await request('/api/admin/partners/cosell',{method:'PUT',body:JSON.stringify({id:Number(b.dataset.acsCancel)})});notify('Co-Sell cancelado');adminCosell(el)}catch(e){notify(e.message)}})}
  async function adminMarketplace(el){const d=await request('/api/admin/partners/marketplace'),jobs=d.jobs||[],sales=d.sales||[];el.innerHTML=`<div class="pc15-card"><h3>Oportunidades</h3>${jobs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Empresa</th><th>Oportunidad</th><th>Comisión</th><th>Cupos</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${E(j.business_name)}</td><td>${E(j.title)}</td><td>${j.commission_percent}%</td><td>${j.slots}</td><td>${statusBadge(j.status)}</td><td>${j.status==='pending_review'?`<button class="pc15-btn good" data-mj-approve="${j.id}">Aprobar</button> <button class="pc15-btn danger" data-mj-reject="${j.id}">Rechazar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin oportunidades','')}</div><div class="pc15-card" style="margin-top:12px"><h3>Ventas Human Sales</h3>${sales.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Empresa / oportunidad</th><th>Especialista</th><th>Venta</th><th>Pool</th><th>Especialista</th><th>WorkticAI</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${sales.map(s=>`<tr><td><b>${E(s.business_name)}</b><small>${E(s.job_title)}</small></td><td>${E(s.specialist_name)}</td><td>${M(s.gross_sale_amount)}</td><td>${M(s.commission_pool)}</td><td>${M(s.specialist_amount)}</td><td>${M(s.platform_amount)}</td><td>${statusBadge(s.status)}</td><td>${s.status==='business_confirmed'?`<button class="pc15-btn good" data-ms-fund="${s.id}">Fondear y aprobar</button>`:''}${s.status==='approved'?`<button class="pc15-btn danger" data-ms-reverse="${s.id}">Reversar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin ventas','')}</div>`;const jobAct=(id,action)=>request('/api/admin/partners/marketplace',{method:'PUT',body:JSON.stringify({kind:'job',id:Number(id),action})}).then(()=>{notify('Oportunidad actualizada');adminMarketplace(el)}).catch(e=>notify(e.message));$$('[data-mj-approve]').forEach(b=>b.onclick=()=>jobAct(b.dataset.mjApprove,'approve'));$$('[data-mj-reject]').forEach(b=>b.onclick=()=>jobAct(b.dataset.mjReject,'reject'));$$('[data-ms-fund]').forEach(b=>b.onclick=async()=>{const ref=prompt('Referencia de fondeo / settlement:','');if(!ref)return;try{await request('/api/admin/partners/marketplace',{method:'PUT',body:JSON.stringify({kind:'sale',id:Number(b.dataset.msFund),action:'fund_and_approve',funding_reference:ref})});notify('Venta aprobada y comisión registrada');adminMarketplace(el)}catch(e){notify(e.message)}});$$('[data-ms-reverse]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Reversar esta venta Human Sales?'))return;try{await request('/api/admin/partners/marketplace',{method:'PUT',body:JSON.stringify({kind:'sale',id:Number(b.dataset.msReverse),action:'reverse',note:'Reverso administrativo'})});notify('Venta reversada');adminMarketplace(el)}catch(e){notify(e.message)}})}
  async function adminPayouts(el){const xs=await request('/api/admin/partners/payouts');el.innerHTML=xs.length?`<div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Partner</th><th>Monto</th><th>Método</th><th>Destino</th><th>Estado</th><th>Referencia</th><th>Acciones</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.partner_name)}</b><small>${E(x.partner_email)}</small></td><td><b>${M(x.amount)}</b></td><td>${E(x.method)}</td><td>${E(x.destination)}</td><td>${statusBadge(x.status)}</td><td>${E(x.reference||'—')}</td><td><div class="pa15-inline">${['requested','needs_review'].includes(x.status)?`<button class="pc15-btn good" data-poa="approve" data-id="${x.id}">Aprobar</button><button class="pc15-btn danger" data-poa="reject" data-id="${x.id}">Rechazar</button>`:''}${x.status==='approved'?`<button class="pc15-btn secondary" data-poa="processing" data-id="${x.id}">En proceso</button><button class="pc15-btn" data-poa="pay" data-id="${x.id}">Pagar</button>`:''}${x.status==='processing'?`<button class="pc15-btn" data-poa="pay" data-id="${x.id}">Registrar pago</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Sin payouts','');$$('[data-poa]').forEach(b=>b.onclick=async()=>{const action=b.dataset.poa;let reference='',note='';if(action==='pay'){reference=prompt('Hash / referencia / comprobante de pago:','')||'';if(!reference)return}else if(action==='reject'){note=prompt('Motivo del rechazo:','')||''}try{await request('/api/admin/partners/payouts',{method:'PUT',body:JSON.stringify({id:Number(b.dataset.id),action,note,reference})});notify('Payout actualizado');adminPayouts(el)}catch(e){notify(e.message)}})}
  async function adminCertifications(el){const xs=await request('/api/admin/partners/certifications');el.innerHTML=`<div class="pc15-card"><div class="pc15-form"><div class="pc15-form-grid"><label>User ID<input id="certUID" type="number" min="1"></label><label>Acción<select id="certAction"><option value="certify">Certificar manualmente</option><option value="revoke">Revocar</option></select></label></div><div class="pc15-form-actions"><button class="pc15-btn" id="certSave">Aplicar</button></div></div></div>${xs.length?`<div class="pc15-card" style="margin-top:12px"><div class="pc15-table-wrap"><table class="pc15-table"><thead><tr><th>Partner</th><th>Examen</th><th>Nota</th><th>Certificado</th><th>Fuente</th><th>Estado</th><th>Emitido</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${E(x.name)}</b><small>${E(x.email)} · ID ${x.partner_user_id}</small></td><td>${E(x.exam_code)}</td><td>${x.score}/${x.passing_score}</td><td>${x.certificate_url?`<a href="${E(x.certificate_url)}" target="_blank" rel="noopener">${E(x.certificate_id||'Ver')}</a>`:E(x.certificate_id||'—')}</td><td>${E(x.source)}</td><td>${statusBadge(x.status)}</td><td>${D(x.issued_at)}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;$('#certSave').onclick=async()=>{try{await request('/api/admin/partners/certifications',{method:'PUT',body:JSON.stringify({user_id:Number($('#certUID').value),action:$('#certAction').value,score:100,passing_score:80})});notify('Certificación actualizada');adminCertifications(el)}catch(e){notify(e.message)}}}
  async function adminSettings(el){const [settings,ranks]=await Promise.all([request('/api/admin/partners/settings'),request('/api/admin/partners/ranks')]);const fields=[['commission_hold_days','Hold comisiones (días)','number'],['adoption_score_min','Impact Score mínimo','number'],['adoption_percent','Adopción %','number'],['renewal_percent','Renovación %','number'],['mentorship_percent','Mentoría %','number'],['mentorship_min_rank','Rango mínimo mentor','text'],['cosell_referrer_split','Co-Sell referidor %','number'],['human_sales_specialist_percent','Human Sales especialista %','number'],['human_sales_platform_percent','Human Sales WorkticAI %','number'],['human_sales_hold_days','Human Sales hold días','number'],['payout_min_amount','Payout mínimo USD','number'],['rank_protection_days','Protección rango días','number'],['academy_activate_exam_code','Código examen Academy','text']];el.innerHTML=`<div class="pc15-card"><div class="pc15-card-head"><div><h3>Reglas del programa</h3><p>Cambios auditables para nuevas operaciones.</p></div><button class="pc15-btn" id="paSettingsSave">Guardar reglas</button></div><div class="pa15-settings">${fields.map(([k,n,t])=>`<div class="pa15-setting"><label>${E(n)}<input data-pas="${k}" type="${t}" value="${E(settings[k]??'')}"></label></div>`).join('')}</div></div><div class="pc15-card" style="margin-top:12px"><div class="pc15-card-head"><div><h3>Worktic Momentum</h3><p>Edita requisitos y porcentajes por rango.</p></div></div><div class="pa15-rank-edit">${ranks.map(r=>`<div class="pa15-rank-card" data-rank-card="${r.code}"><h4>${E(r.name)}</h4><label>Clientes<input data-rf="direct" type="number" value="${r.min_direct_active}"></label><label>Adopción<input data-rf="adopted" type="number" value="${r.min_adopted}"></label><label>Directa %<input data-rf="directpct" type="number" step="0.1" value="${r.direct_percent}"></label><label>N2 %<input data-rf="n2" type="number" step="0.1" value="${r.level2_percent}"></label><label>N3 %<input data-rf="n3" type="number" step="0.1" value="${r.level3_percent}"></label><button class="pc15-btn secondary" data-rank-save="${r.code}">Guardar</button></div>`).join('')}</div></div>`;$('#paSettingsSave').onclick=async()=>{const q={};$$('[data-pas]').forEach(i=>q[i.dataset.pas]=i.value);try{await request('/api/admin/partners/settings',{method:'PUT',body:JSON.stringify(q)});notify('Reglas Partner actualizadas')}catch(e){notify(e.message)}};$$('[data-rank-save]').forEach(b=>b.onclick=async()=>{const card=b.closest('[data-rank-card]');const val=k=>Number(card.querySelector(`[data-rf="${k}"]`).value);try{await request('/api/admin/partners/ranks',{method:'PUT',body:JSON.stringify({code:b.dataset.rankSave,min_direct_active:val('direct'),min_adopted:val('adopted'),direct_percent:val('directpct'),level2_percent:val('n2'),level3_percent:val('n3')})});notify('Rango actualizado')}catch(e){notify(e.message)}})}

  // Partner admin tab is not loaded by admin-full.js, so attach it here after that script initializes.
  const adminPartnerTab=document.querySelector('.wt-admin-tab[data-admin-tab="partners"]');
  if(adminPartnerTab){adminPartnerTab.onclick=()=>{$$('.wt-admin-tab').forEach(x=>x.classList.toggle('active',x===adminPartnerTab));$$('.wt-admin-panel').forEach(x=>x.classList.toggle('active',x.dataset.adminPanel==='partners'));loadPartnerAdminV2715();}}
})();
